1	// Acceptance test for the change request:
2	//   "Do not really delete a project. Just tuck it away so it drops off my lists. Keep it off the
3	//    main project list and off the list on the client's page. I do not want to lose anything.
4	//    Note it when I do."
5	//
6	// Archiving is a NON-destructive "tuck away", distinct from deleting. Each project row offers a
7	// control to archive it (project-archive-<id>). Archiving:
8	//   * drops the project from the main projects list (projects-table / project-row-<id>),
9	//   * drops it from the list on its client's detail page (client-projects-table),
10	//   * is held by the SERVER (it survives a fresh load),
11	//   * keeps a record — exactly one audit record `PROJECT_ARCHIVED id=<id>` per archive,
12	//   * LOSES NOTHING: the projects page carries a Show-archived toggle (projects-show-archived)
13	//     that reveals archived projects again.
14	// Archiving one project must not touch its siblings, and merely viewing or revealing a list records
15	// nothing — only the archive action itself does.
16	//
17	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
18	// (auditLines()). Data is arranged via resetAndSeed (the app's /__test__ endpoint): `clients`
19	// honours { id, name, email } and `projects` honours { id, name, clientId, archived }.
20	import { test, expect, type Page } from '@playwright/test';
21	import { resetAndSeed } from '../support/seed';
22	import { auditLines } from '../support/audit';
23	
24	const projectRows = (page: Page) => page.locator('[data-testid^="project-row-"]');
25	
26	// The audit record for one archive — carries the project's id and nothing else; matched exactly.
27	const archivedRecord = (id: number) => `PROJECT_ARCHIVED id=${id}`;
28	
29	const archivedRecordsFor = (id: number): string[] =>
30	  auditLines().filter((line) => line === archivedRecord(id));
31	
32	test.describe('Archive a project', () => {
33	  test('archiving a project drops it from the list, persists, keeps the project, and records it once', async ({
34	    page,
35	  }) => {
36	    await resetAndSeed({
37	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
38	      projects: [{ id: 1, name: 'Website Redesign', clientId: 1 }],
39	    });
40	
41	    await page.goto('/projects');
42	    await expect(page.getByTestId('projects-page')).toBeVisible();
43	
44	    // The project is listed and offers a control to archive it; the page offers the Show-archived
45	    // toggle that will later reveal it again.
46	    await expect(projectRows(page)).toHaveCount(1);
47	    await expect(page.getByTestId('project-row-1')).toBeVisible();
48	    const archive = page.getByTestId('project-archive-1');
49	    await expect(archive).toBeVisible();
50	    await expect(page.getByTestId('projects-show-archived')).toBeVisible();
51	
52	    // Nothing has been recorded yet — reset clears the audit file, so the record below is proof the
53	    // archiving (not the seeding) wrote it.
54	    expect(auditLines()).toEqual([]);
55	
56	    await archive.click();
57	
58	    // The project drops off the main list — tucked away, it is the only project so the list is now
59	    // empty.
60	    await expect(page.getByTestId('project-row-1')).toHaveCount(0);
61	    await expect(projectRows(page)).toHaveCount(0);
62	    await expect(page.getByTestId('projects-empty')).toBeVisible();
63	
64	    // Exactly one record was kept for this archive, carrying the project's id.
65	    expect(archivedRecordsFor(1)).toHaveLength(1);
66	    expect(auditLines()).toHaveLength(1);
67	
68	    // The tuck-away is held by the server, not just the page: it survives a fresh load, and merely
69	    // viewing the list does not record the archive a second time.
70	    await page.reload();
71	    await expect(page.getByTestId('project-row-1')).toHaveCount(0);
72	    await expect(page.getByTestId('projects-empty')).toBeVisible();
73	    expect(archivedRecordsFor(1)).toHaveLength(1);
74	    expect(auditLines()).toHaveLength(1);
75	
76	    // Nothing was lost: revealing archived projects brings it back, still carrying its name. And
77	    // revealing is a view — it records nothing.
78	    await page.getByTestId('projects-show-archived').click();
79	    await expect(page.getByTestId('project-row-1')).toBeVisible();
80	    await expect(page.getByTestId('project-row-1').getByTestId('project-name')).toHaveText(
81	      'Website Redesign',
82	    );
83	    await expect(page.getByTestId('projects-empty')).toHaveCount(0);
84	    expect(archivedRecordsFor(1)).toHaveLength(1);
85	    expect(auditLines()).toHaveLength(1);
86	  });
87	
88	  test('archiving one project leaves the others on the list, and each archive keeps its own record', async ({
89	    page,
90	  }) => {
91	    await resetAndSeed({
92	      clients: [
93	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
94	        { id: 2, name: 'Globex', email: 'contact@globex.test' },
95	      ],
96	      projects: [
97	        { id: 1, name: 'Website Redesign', clientId: 1 },
98	        { id: 2, name: 'Mobile App', clientId: 2 },
99	        { id: 3, name: 'Billing System', clientId: 1 },
100	      ],
101	    });
102	
103	    await page.goto('/projects');
104	    await expect(projectRows(page)).toHaveCount(3);
105	    expect(auditLines()).toEqual([]);
106	
107	    // Archive the middle project.
108	    await page.getByTestId('project-archive-2').click();
109	
110	    // Only that project is tucked away; its siblings remain, each still carrying its name and client.
111	    await expect(page.getByTestId('project-row-2')).toHaveCount(0);
112	    await expect(projectRows(page)).toHaveCount(2);
113	    await expect(page.getByTestId('project-row-1').getByTestId('project-name')).toHaveText(
114	      'Website Redesign',
115	    );
116	    await expect(page.getByTestId('project-row-1').getByTestId('project-client')).toHaveText(
117	      'Acme Corp',
118	    );
119	    await expect(page.getByTestId('project-row-3').getByTestId('project-name')).toHaveText(
120	      'Billing System',
121	    );
122	
123	    // Exactly one record so far, for the project that was archived.
124	    expect(archivedRecordsFor(2)).toHaveLength(1);
125	    expect(auditLines()).toHaveLength(1);
126	
127	    // Archive another project — a second record is kept, independent of the first.
128	    await page.getByTestId('project-archive-1').click();
129	    await expect(page.getByTestId('project-row-1')).toHaveCount(0);
130	    await expect(projectRows(page)).toHaveCount(1);
131	    await expect(page.getByTestId('project-row-3')).toBeVisible();
132	
133	    expect(archivedRecordsFor(2)).toHaveLength(1);
134	    expect(archivedRecordsFor(1)).toHaveLength(1);
135	    expect(auditLines()).toHaveLength(2);
136	
137	    // The tuck-aways survive a fresh load: only the un-archived project remains on the list.
138	    await page.reload();
139	    await expect(projectRows(page)).toHaveCount(1);
140	    await expect(page.getByTestId('project-row-3')).toBeVisible();
141	    await expect(page.getByTestId('project-row-1')).toHaveCount(0);
142	    await expect(page.getByTestId('project-row-2')).toHaveCount(0);
143	    expect(auditLines()).toHaveLength(2);
144	
145	    // Nothing was lost: revealing archived projects brings both back, so all three are shown again.
146	    await page.getByTestId('projects-show-archived').click();
147	    await expect(projectRows(page)).toHaveCount(3);
148	    await expect(page.getByTestId('project-row-1')).toBeVisible();
149	    await expect(page.getByTestId('project-row-2')).toBeVisible();
150	    await expect(page.getByTestId('project-row-3')).toBeVisible();
151	    // Revealing is a view — it records nothing.
152	    expect(auditLines()).toHaveLength(2);
153	  });
154	
155	  test('a project seeded archived starts off the list and is revealed by the Show-archived toggle', async ({
156	    page,
157	  }) => {
158	    await resetAndSeed({
159	      clients: [{ id: 1, name: 'Acme Corp', email: 'hello@acme.test' }],
160	      projects: [
161	        { id: 1, name: 'Active Work', clientId: 1 },
162	        // Already tucked away: it must not show on the list until archived projects are revealed.
163	        { id: 2, name: 'Tucked Away', clientId: 1, archived: true },
164	      ],
165	    });
166	
167	    await page.goto('/projects');
168	    await expect(page.getByTestId('projects-page')).toBeVisible();
169	    await expect(page.getByTestId('projects-table')).toBeVisible();
170	
171	    // Only the un-archived project is listed by default; the archived one is off the list.
172	    await expect(projectRows(page)).toHaveCount(1);
173	    await expect(page.getByTestId('project-row-1')).toBeVisible();
174	    await expect(page.getByTestId('project-row-1').getByTestId('project-name')).toHaveText(
175	      'Active Work',
176	    );
177	    await expect(page.getByTestId('project-row-2')).toHaveCount(0);
