3	import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
4	import { useSearchParam, asFlag, asString } from '../../url/useSearchParam';
5	import { useProjects } from './projects';
6	
7	// The projects list. Reads server data straight from its query key and shows the client's NAME
8	// (served alongside each project), not the id. Archived projects are tucked away: they drop off the
9	// list unless the shared `showArchived` URL key (set by a toolbar control) reveals them.
10	export function ProjectList() {
11	  const { data: projects } = useProjects();
12	  const [showArchived] = useSearchParam('showArchived', asFlag);
13	  // Shared with the tag-filter toolbar control via the `projectTag` key (no import). When set, keep
14	  // only projects carrying that tag; empty shows every tag.
15	  const [tagFilter] = useSearchParam('projectTag', asString);
16	
17	  if (!projects) {
18	    return null;
19	  }
20	
21	  if (projects.length === 0) {
22	    return <p data-testid="projects-empty">No projects yet.</p>;
23	  }
24	
25	  const tagId = tagFilter === '' ? undefined : Number(tagFilter);
26	  const shown = projects
27	    .filter((project) => showArchived || !project.archived)
28	    .filter((project) => tagId === undefined || project.tagIds.includes(tagId));
29	
30	  return (
31	    <>
32	    <ProjectsToolbar.Slot />
33	    <table data-testid="projects-table">
34	      <thead>
35	        <tr>
36	          <th>Name</th>
37	          <th>Client</th>
38	          <th></th>
39	        </tr>
40	      </thead>
41	      <tbody>
42	        {shown.map((project) => (
43	          <tr key={project.id} data-testid={`project-row-${project.id}`}>
44	            <td data-testid="project-name">{project.name}</td>
45	            <td data-testid="project-client">{project.clientName}</td>
46	            <td>
47	              <Link
48	                to="/projects/$projectId"
49	                params={{ projectId: String(project.id) }}
50	                data-testid={`project-open-${project.id}`}
51	              >
52	                Open
53	              </Link>
54	            </td>
55	            <td>
56	              <ProjectRow.Slot project={project} />
57	            </td>
58	          </tr>
59	        ))}
60	      </tbody>
61	    </table>
